-- Do not edit by hand; change the mapping or the converter and regenerate.
-- Flow: SQ_RAW_STORES -> EXP_LOCATIONS -> SRT_LOC_BEFORE -> RTR_REGION -> SRT_APAC -> EXP_APAC_RENAME_TRANS -> SRT_EMEA -> EXP_EMEA_RENAME_TRANS -> SRT_AMER -> EXP_AMER_RENAME_TRANS -> UN_REGIONS -> SRT_LOC_AFTER -> STG_LOCATIONS
-- WARNING [RTR_REGION]: Router sends a row to EVERY group whose condition is true (not just the first)

with

sq_raw_stores as (
    -- SQ_RAW_STORES (Source Qualifier): reads RAW_STORES
    select
        cast(id as varchar) as id,
        cast(name as varchar) as name,
        cast(opened_at as timestamp) as opened_at,
        cast(tax_rate as decimal(6, 4)) as tax_rate
    from {{ source('raw', 'raw_stores') }}
),

exp_locations as (
    -- EXP_LOCATIONS (Expression)
    select
        id as location_id,
        name as location_name,
        date_trunc('day', opened_at) as opened_date,
        tax_rate as tax_rate,
        case when (tax_rate >= 0.15) then 'EMEA' else case when (tax_rate >= 0.09) then 'APAC' else 'AMER' end end as region
    from sq_raw_stores
),

srt_loc_before as (
    -- SRT_LOC_BEFORE (Sorter on location_id asc): row order only matters to order-dependent logic downstream, so no ORDER BY here
    select
        location_id as location_id,
        location_name as location_name,
        opened_date as opened_date,
        tax_rate as tax_rate,
        region as region
    from exp_locations
),

rtr_region__g_apac as (
    -- RTR_REGION (Router) group G_APAC: REGION = 'APAC'
    select
        location_id as location_id1,
        location_name as location_name1,
        opened_date as opened_date1,
        tax_rate as tax_rate1,
        region as region1
    from srt_loc_before
    where (region = 'APAC')
),

rtr_region__g_amer as (
    -- RTR_REGION (Router) group G_AMER: REGION = 'AMER'
    select
        location_id as location_id3,
        location_name as location_name3,
        opened_date as opened_date3,
        tax_rate as tax_rate3,
        region as region3
    from srt_loc_before
    where (region = 'AMER')
),

rtr_region__g_emea as (
    -- RTR_REGION (Router) group G_EMEA: REGION = 'EMEA'
    select
        location_id as location_id4,
        location_name as location_name4,
        opened_date as opened_date4,
        tax_rate as tax_rate4,
        region as region4
    from srt_loc_before
    where (region = 'EMEA')
),

srt_apac as (
    -- SRT_APAC (Sorter on location_id1 asc): row order only matters to order-dependent logic downstream, so no ORDER BY here
    select
        location_id1 as location_id1,
        location_name1 as location_name1,
        opened_date1 as opened_date1,
        tax_rate1 as tax_rate1,
        region1 as region1
    from rtr_region__g_apac
),

exp_apac_rename_trans as (
    -- EXP_APAC_RENAME_TRANS (Expression)
    select
        location_id1 as location_id,
        location_name1 as location_name,
        opened_date1 as opened_date,
        tax_rate1 as tax_rate,
        region1 as region
    from srt_apac
),

srt_emea as (
    -- SRT_EMEA (Sorter on location_id4 asc): row order only matters to order-dependent logic downstream, so no ORDER BY here
    select
        location_id4 as location_id4,
        location_name4 as location_name4,
        opened_date4 as opened_date4,
        tax_rate4 as tax_rate4,
        region4 as region4
    from rtr_region__g_emea
),

exp_emea_rename_trans as (
    -- EXP_EMEA_RENAME_TRANS (Expression)
    select
        location_id4 as location_id,
        location_name4 as location_name,
        opened_date4 as opened_date,
        tax_rate4 as tax_rate,
        region4 as region
    from srt_emea
),

srt_amer as (
    -- SRT_AMER (Sorter on location_id3 asc): row order only matters to order-dependent logic downstream, so no ORDER BY here
    select
        location_id3 as location_id3,
        location_name3 as location_name3,
        opened_date3 as opened_date3,
        tax_rate3 as tax_rate3,
        region3 as region3
    from rtr_region__g_amer
),

exp_amer_rename_trans as (
    -- EXP_AMER_RENAME_TRANS (Expression)
    select
        location_id3 as location_id,
        location_name3 as location_name,
        opened_date3 as opened_date,
        tax_rate3 as tax_rate,
        region3 as region
    from srt_amer
),

un_regions as (
    -- UN_REGIONS (Union): UNION ALL of 3 input groups
    -- input group APAC
    select
        location_id as location_id,
        location_name as location_name,
        opened_date as opened_date,
        tax_rate as tax_rate,
        region as region
    from exp_apac_rename_trans

    union all

    -- input group AMER
    select
        location_id as location_id,
        location_name as location_name,
        opened_date as opened_date,
        tax_rate as tax_rate,
        region as region
    from exp_amer_rename_trans

    union all

    -- input group EMEA
    select
        location_id as location_id,
        location_name as location_name,
        opened_date as opened_date,
        tax_rate as tax_rate,
        region as region
    from exp_emea_rename_trans
),

srt_loc_after as (
    -- SRT_LOC_AFTER (Sorter on location_id asc): row order only matters to order-dependent logic downstream, so no ORDER BY here
    select
        location_id as location_id,
        location_name as location_name,
        opened_date as opened_date,
        tax_rate as tax_rate,
        region as region
    from un_regions
